import { useCallback, useContext, useEffect, useState } from 'react'
import type { NewExpense } from '../../application/ExpenseGateway'
import type { ExpenseViewModel } from '../../application/ExpenseViewModel'
import { ExpensesContext } from '../ExpensesContext/ExpensesContext'

export const useExpenses = () => {
  const useCases = useContext(ExpensesContext)
  if (!useCases) throw new Error('useExpenses needs an ExpensesContext provider')
  const { listExpenses, submitExpense } = useCases

  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    let active = true
    listExpenses
      .execute()
      .then((items) => active && setExpenses(items))
      .catch((error: Error) => active && setLoadError(error.message))
      .finally(() => active && setLoading(false))
    return () => {
      active = false
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<boolean> => {
      setSubmitting(true)
      setSubmitError(null)
      try {
        const result = await submitExpense.execute(expense)
        if (!result.ok) {
          setFieldErrors(result.errors)
          return false
        }
        setFieldErrors({})
        setExpenses(await listExpenses.execute())
        return true
      } catch (error) {
        setSubmitError(error instanceof Error ? error.message : 'Submission failed')
        return false
      } finally {
        setSubmitting(false)
      }
    },
    [listExpenses, submitExpense],
  )

  return { expenses, loading, loadError, submit, submitting, fieldErrors, submitError }
}
