import { useState, type SubmitEventHandler } from 'react'
import type { NewExpense } from '../../application/ExpenseGateway'

type ExpenseFormProps = {
  onSubmit: (expense: NewExpense) => Promise<boolean>
  submitting: boolean
  errors: Record<string, string>
  submitError: string | null
}

export const ExpenseForm = ({ onSubmit, submitting, errors, submitError }: ExpenseFormProps) => {
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')

  const handleSubmit: SubmitEventHandler<HTMLFormElement> = async (event) => {
    event.preventDefault()
    const done = await onSubmit({ label, amount: Number(amount), currency })
    if (done) {
      setLabel('')
      setAmount('')
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="expense-label">Label</label>
        <input
          id="expense-label"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          aria-invalid={Boolean(errors.label)}
          aria-describedby={errors.label ? 'expense-label-error' : undefined}
        />
        {errors.label && <span id="expense-label-error" role="alert">{errors.label}</span>}
      </div>
      <div>
        <label htmlFor="expense-amount">Amount</label>
        <input
          id="expense-amount"
          type="number"
          step="0.01"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          aria-invalid={Boolean(errors.amount)}
          aria-describedby={errors.amount ? 'expense-amount-error' : undefined}
        />
        {errors.amount && <span id="expense-amount-error" role="alert">{errors.amount}</span>}
      </div>
      <div>
        <label htmlFor="expense-currency">Currency</label>
        <input
          id="expense-currency"
          value={currency}
          onChange={(e) => setCurrency(e.target.value)}
          aria-invalid={Boolean(errors.currency)}
          aria-describedby={errors.currency ? 'expense-currency-error' : undefined}
        />
        {errors.currency && <span id="expense-currency-error" role="alert">{errors.currency}</span>}
      </div>
      {submitError && <p role="alert">{submitError}</p>}
      <button type="submit" disabled={submitting}>Submit expense</button>
    </form>
  )
}
